import{_ as a,o as n,c as e,a5 as t}from"./chunks/framework.R-FQ1xZ2.js";const b=JSON.parse('{"title":"如何使用这个站","description":"","frontmatter":{"title":"如何使用这个站"},"headers":[],"relativePath":"roadmap/how-to-use.md","filePath":"roadmap/how-to-use.md","lastUpdated":null}'),i={name:"roadmap/how-to-use.md"};function d(p,s,l,r,o,c){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="如何使用这个站" tabindex="-1">如何使用这个站 <a class="header-anchor" href="#如何使用这个站" aria-label="Permalink to &quot;如何使用这个站&quot;">​</a></h1><h2 id="一、启动与访问" tabindex="-1">一、启动与访问 <a class="header-anchor" href="#一、启动与访问" aria-label="Permalink to &quot;一、启动与访问&quot;">​</a></h2><p>在 <code>D:\\AI-Learning</code> 目录下双击 <code>start.cmd</code>，或者手动跑：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> D:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\A</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">I-Learning</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 构建静态站（约 4 秒）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 起本地服务，默认 http://localhost:3000</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>想边写边看效果，用热更新模式：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # http://localhost:5173</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">为什么不是纯静态</p><p>普通的 VitePress 静态站不能调用 DeepSeek（API Key 会暴露在浏览器里）。这个站在静态站外面套了一层本地 Node 服务：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器 ──► Express:3000 ──► DeepSeek API</span></span>
<span class="line"><span>             │</span></span>
<span class="line"><span>             ├─ 静态托管 docs/.vitepress/dist</span></span>
<span class="line"><span>             ├─ BM25 站内检索（我的笔记全文）</span></span>
<span class="line"><span>             └─ 笔记落盘 docs/inbox/*.md</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>API Key 只存在服务端的 <code>.env</code> 里，永远不进浏览器。</p></div><h2 id="二、右侧助教怎么用" tabindex="-1">二、右侧助教怎么用 <a class="header-anchor" href="#二、右侧助教怎么用" aria-label="Permalink to &quot;二、右侧助教怎么用&quot;">​</a></h2><p>页面右下角的悬浮按钮打开对话助手。它不是一个通用聊天机器人，它是一个<strong>读过这个站所有笔记的资深 AI 开发工程师 + 校招技术面试官</strong>。</p><p>它能做四件事：</p><table tabindex="0"><thead><tr><th>用法</th><th>怎么问</th><th>它会怎么答</th></tr></thead><tbody><tr><td>讲原理</td><td>「LangGraph 的 checkpointer 到底存了什么？」</td><td>先给结论，再讲机制，能画的直接给 Mermaid 图</td></tr><tr><td>对项目</td><td>「我 YYHelp 里那个中文 BM25 失效，面试官会怎么追问？」</td><td>挂靠站内对应页面，给追问链与答法</td></tr><tr><td>出题考我</td><td>「考我三题 RAG 检索，从易到难」</td><td>按面试官视角出题，我答完它点评</td></tr><tr><td>存笔记</td><td>答得好的内容点「存为笔记」</td><td>写进 <code>docs/inbox/</code>，自动重建站点并进侧栏</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">它不干什么</p><ul><li>不编造 API 名、参数默认值、版本号 —— 拿不准它会直接说拿不准</li><li>不替我美化经历或编数字 —— 面试被追问三层会崩</li><li>不设置对话条数上限，本地用的东西不需要防</li></ul></div><h3 id="填-api-key" tabindex="-1">填 API Key <a class="header-anchor" href="#填-api-key" aria-label="Permalink to &quot;填 API Key&quot;">​</a></h3><p>编辑 <code>D:\\AI-Learning\\.env</code>：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEEPSEEK_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sk-在这里填你自己的</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEEPSEEK_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">deepseek-chat</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEEPSEEK_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://api.deepseek.com</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KB_TOP_K</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">5</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>改完<strong>重启服务</strong>（Ctrl+C 后重新 <code>npm run serve</code>）才生效。没填 Key 时助手栏会显示黄色告警条，其余功能照常可用。</p><h2 id="三、检索习惯" tabindex="-1">三、检索习惯 <a class="header-anchor" href="#三、检索习惯" aria-label="Permalink to &quot;三、检索习惯&quot;">​</a></h2><p>站内搜索（左上角或 <code>Ctrl+K</code>）用的是<strong>中文友好的 BM25</strong>，不是简单字符串匹配：</p><ul><li>中文按 <strong>bigram</strong> 切，所以「混合检索」和「检索混合」都能命中</li><li>标题命中加权，所以标题里带这个词的页面排前面</li><li>同一个文件最多出两个片段，避免一个长页面刷屏</li></ul><p>搜不到想要的，换<strong>英文术语</strong>再搜一次 —— 页面里所有技术名词都保留英文原词（RAG、RRF、Rerank、checkpointer、interrupt），用这些词命中率最高。</p><h2 id="四、这个站的组织方式" tabindex="-1">四、这个站的组织方式 <a class="header-anchor" href="#四、这个站的组织方式" aria-label="Permalink to &quot;四、这个站的组织方式&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>学习路线   ← 你在这</span></span>
<span class="line"><span>  ├─ 路线总览      该怎么走、每周交什么</span></span>
<span class="line"><span>  ├─ 进度看板      打勾、错题本、投递台账</span></span>
<span class="line"><span>  └─ 如何使用      本页</span></span>
<span class="line"><span></span></span>
<span class="line"><span>项目拆解   ← 我的两个真实项目，按模块拆到能扛住追问</span></span>
<span class="line"><span>  ├─ YYHelp 电商客服 Agent   18 页</span></span>
<span class="line"><span>  └─ 科研文献 RAG 问答       15 页</span></span>
<span class="line"><span></span></span>
<span class="line"><span>知识体系   ← 185 个知识点，一个知识点 = 一页</span></span>
<span class="line"><span>  └─ L0 → L7</span></span>
<span class="line"><span></span></span>
<span class="line"><span>架构图库   ← 所有原理图，可全屏打开</span></span>
<span class="line"><span>  └─ 按主题分组</span></span>
<span class="line"><span></span></span>
<span class="line"><span>面试       ← 高频题、手撕、项目深挖预演</span></span>
<span class="line"><span></span></span>
<span class="line"><span>收件箱     ← 助教帮我存下来的笔记</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><p><strong>三条主线的关系</strong>：</p><ul><li><strong>项目拆解</strong>回答「我做过什么」，是简历的弹药库</li><li><strong>知识体系</strong>回答「我懂什么原理」，是面试的底层</li><li><strong>架构图库</strong>回答「能不能画给我看」，是表达工具</li></ul><p>同一个主题通常三处都有：项目页讲<strong>我的实现</strong>，知识页讲<strong>通用原理</strong>，图库给<strong>视觉骨架</strong>。建议的阅读顺序是 <strong>图 → 知识页 → 项目页</strong>：先用图建立空间感，再看原理，最后落到自己的代码上。</p><h2 id="五、学习方法-这个站的用法约定" tabindex="-1">五、学习方法（这个站的用法约定） <a class="header-anchor" href="#五、学习方法-这个站的用法约定" aria-label="Permalink to &quot;五、学习方法（这个站的用法约定）&quot;">​</a></h2><h3 id="不要「看完再做」" tabindex="-1">不要「看完再做」 <a class="header-anchor" href="#不要「看完再做」" aria-label="Permalink to &quot;不要「看完再做」&quot;">​</a></h3><p>707 小时的量，看完再做就已经错过窗口了。改成 <strong>边看边交付</strong>：每学一个知识点，立刻问自己「我能在哪个项目里用上 / 我项目里哪个地方印证了它」，然后写一句话记下来。</p><h3 id="每页的「和你自己的项目对上号」是重点" tabindex="-1">每页的「和你自己的项目对上号」是重点 <a class="header-anchor" href="#每页的「和你自己的项目对上号」是重点" aria-label="Permalink to &quot;每页的「和你自己的项目对上号」是重点&quot;">​</a></h3><p>这一节把通用原理拉回到我自己的代码上。跳过它，这一页就只是别人的博客；读了它，这一页才是我的面试素材。</p><h3 id="「面试怎么问」要出声念一遍" tabindex="-1">「面试怎么问」要出声念一遍 <a class="header-anchor" href="#「面试怎么问」要出声念一遍" aria-label="Permalink to &quot;「面试怎么问」要出声念一遍&quot;">​</a></h3><p>默读会骗人。念出来才知道自己哪一句是卡壳的。卡壳的地方就是没真懂的地方。</p><h3 id="学完一个知识点-去助教那里考一次" tabindex="-1">学完一个知识点，去助教那里考一次 <a class="header-anchor" href="#学完一个知识点-去助教那里考一次" aria-label="Permalink to &quot;学完一个知识点，去助教那里考一次&quot;">​</a></h3><p>让它按面试官视角出题。答不上来的直接进 <a href="/learn/roadmap/progress.html">进度看板</a> 的错题本。</p><h3 id="每场面试后必须回填错题本" tabindex="-1">每场面试后必须回填错题本 <a class="header-anchor" href="#每场面试后必须回填错题本" aria-label="Permalink to &quot;每场面试后必须回填错题本&quot;">​</a></h3><p>被问到但答不好的问题，是最真实的缺口清单。投递期最值钱的就是这张表。</p><h2 id="六、维护" tabindex="-1">六、维护 <a class="header-anchor" href="#六、维护" aria-label="Permalink to &quot;六、维护&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我改了……</th><th>要跑什么</th></tr></thead><tbody><tr><td><code>docs/**/*.md</code>（笔记正文）</td><td>服务会自动检测改动并重建（最多 5 秒延迟）；也可手动 <code>npm run docs:build</code></td></tr><tr><td>知识体系页面增删</td><td><code>node scripts/build-kb-sidebar.mjs</code> 再 build</td></tr><tr><td><code>diagrams/_meta.json</code>（图库清单）</td><td><code>node scripts/build-diagrams.mjs</code> 再 build</td></tr><tr><td><code>.env</code></td><td>重启 <code>npm run serve</code></td></tr><tr><td>图候选 JSON（<code>diagrams/src/</code>）</td><td>重新 <code>archify deliver</code>，把 HTML 放到 <code>docs/public/diagrams/</code>，再跑 build-diagrams</td></tr></tbody></table><details class="details custom-block"><summary>目录速查</summary><table tabindex="0"><thead><tr><th>路径</th><th>作用</th></tr></thead><tbody><tr><td><code>docs/</code></td><td>站点源码（VitePress）</td></tr><tr><td><code>docs/.vitepress/config.mts</code></td><td>站点配置：导航、侧栏、搜索、MathJax</td></tr><tr><td><code>docs/.vitepress/theme/</code></td><td>自定义主题：对话助手、Mermaid、图框样式</td></tr><tr><td><code>docs/public/diagrams/</code></td><td>archify 交付的原始 HTML（可直接全屏打开）</td></tr><tr><td><code>docs/public/fig/</code></td><td>构建时自动搬过来的图（避免路径冲突）</td></tr><tr><td><code>docs/kb/</code></td><td>知识体系 L0–L7</td></tr><tr><td><code>docs/projects/</code></td><td>两个项目的拆解页</td></tr><tr><td><code>docs/diagrams/</code></td><td>图库的说明页（iframe 内嵌图）</td></tr><tr><td><code>docs/inbox/</code></td><td>助教存下来的笔记</td></tr><tr><td><code>server/</code></td><td>本地服务：SSE 代理、BM25 检索、笔记落盘</td></tr><tr><td><code>scripts/</code></td><td>构建脚本：图库生成、知识体系侧栏</td></tr><tr><td><code>diagrams/src/</code></td><td>图的候选 JSON 源文件（可重新交付）</td></tr><tr><td><code>_research/</code></td><td>知识体系大纲与原始抓取物（不进站点）</td></tr><tr><td><code>_specs/</code></td><td>写作规范与图规格</td></tr></tbody></table></details>`,39)])])}const k=a(i,[["render",d]]);export{b as __pageData,k as default};
